const originalPhone = String($json.originalPhone || $json.phone || $json.from || $json.senderPhone || $json.normalizedMessage?.from || '').trim();
const normalizedPhone = String($json.normalizedPhone || $json.normalized_phone || $json.customer_phone || '').replace(/[^0-9]/g, '');
const whatsappPhone = String($json.wamidPhone || $json.whatsappPhone || $json.normalizedMessage?.from || $json.from || '').replace(/[^0-9]/g, '');
const digits = (normalizedPhone || originalPhone || whatsappPhone).replace(/[^0-9]/g, '').replace(/^00/, '');
const normalizeUaePhone = (value) => {
  const candidate = String(value || '').replace(/[^0-9]/g, '').replace(/^00/, '');
  if (/^9715\d{8}$/.test(candidate)) return { normalizedPhone: candidate, phoneType: 'mobile' };
  if (/^05\d{8}$/.test(candidate)) return { normalizedPhone: '971' + candidate.slice(1), phoneType: 'mobile' };
  if (/^5\d{8}$/.test(candidate)) return { normalizedPhone: '971' + candidate, phoneType: 'mobile' };
  if (/^971[234679]\d{7}$/.test(candidate)) return { normalizedPhone: candidate, phoneType: 'landline' };
  if (/^0[234679]\d{7}$/.test(candidate)) return { normalizedPhone: '971' + candidate.slice(1), phoneType: 'landline' };
  if (/^[234679]\d{7}$/.test(candidate)) return { normalizedPhone: '971' + candidate, phoneType: 'landline' };
  return { normalizedPhone: '', phoneType: 'unknown' };
};
const normalized = normalizeUaePhone(digits || normalizedPhone || whatsappPhone || originalPhone);
const canonical = normalized.normalizedPhone || normalizedPhone || digits || whatsappPhone;
const local = canonical && canonical.startsWith('971') ? '0' + canonical.slice(3) : '';
const shortLocal = canonical && canonical.startsWith('971') ? canonical.slice(3) : '';
const variants = [...new Set([originalPhone, digits, canonical, local, shortLocal, whatsappPhone].filter(Boolean))];
const primaryPhone = canonical || digits || whatsappPhone;
const correlationId = $json.correlationId || $json.normalizedMessage?.correlationId || 'corr_' + Date.now() + '_' + ($execution.id || 'n8n');
return [{ json: { ...$json, originalPhone, normalizedPhone: canonical, phoneType: normalized.phoneType, primaryPhone, phoneVariants: variants, correlationId, workflowExecutionId: String($execution.id || '') } }];

